spec.expr:
histogram_quantile(0.95, 
  sum by (exported_namespace, namespace, cluster, chi, le, label_product, label_project) (
    rate(clickhouse_operator_chi_reconciles_timings_bucket{exported_namespace=~"$namespace", chi=~"$chi", cluster=~"$cluster"}[5m])
    * on(exported_namespace, cluster) group_left(label_product, label_project)
    label_replace(
      kube_namespace_labels{
        label_product=~"$product",
        label_project=~"$project"}, 
      "exported_namespace", "$1", "namespace", "(.*)"
    )
  )
)

sum by (cluster, label_product, label_project) (
  increase(clickhouse_operator_host_reconciles_errors{cluster=~"$cluster"}[5m])
  * on(exported_namespace, cluster) group_left(label_product, label_project)
  label_replace(
    kube_namespace_labels{
        label_product=~"$product",
        label_project=~"$project"}, 
    "exported_namespace", "$1", "namespace", "(.*)"
  )
)

sum by (chi, cluster, label_product, label_project, exported_namespace) (
  increase(clickhouse_operator_host_reconciles_errors{exported_namespace=~"$namespace", chi=~"$chi", cluster=~"$cluster"}[5m])
  * on(exported_namespace, cluster) group_left(label_product, label_project)
  label_replace(
    kube_namespace_labels{
        label_product=~"$product",
        label_project=~"$project"}, 
    "exported_namespace", "$1", "namespace", "(.*)"
  )
)

histogram_quantile(0.95, 
  sum by (cluster, chi, le, label_project, label_product, exported_namespace) (
    rate(clickhouse_operator_host_reconciles_timings_bucket{exported_namespace=~"$namespace", chi=~"$chi", cluster=~"$cluster"}[5m])
    * on(exported_namespace, cluster) group_left(label_project, label_product)
    label_replace(
      kube_namespace_labels{
        label_product=~"$product",
        label_project=~"$project"}, 
      "exported_namespace", "$1", "namespace", "(.*)"
    )
  )
)
